package com.nse.dashboard.agent;import com.nse.dashboard.model.OptionData;import org.springframework.stereotype.Component;import java.util.*;@Component public class OIAnalysisAgent { public Map<String, Double> analyze(List<OptionData> data){ double support=0,resistance=0; long maxPut=0,maxCall=0; for(OptionData d:data){ if(d.getPutOI()>maxPut){maxPut=d.getPutOI();support=d.getStrike();} if(d.getCallOI()>maxCall){maxCall=d.getCallOI();resistance=d.getStrike();}} Map<String,Double> r=new HashMap<>(); r.put("support",support); r.put("resistance",resistance); return r;}}